gyd(){return"\u0a88\u0aae\u0ac7\u0ab2 \u0ab8\u0aab\u0ab3\u0aa4\u0abe\u0aaa\u0ac2\u0ab0\u0acd\u0ab5\u0a95 \u0ab5\u0ac7\u0ab0\u0abf\u0aab\u0abe\u0aaf \u0aa5\u0aaf\u0acb."},
gyT(){return"\u0a85\u0aae\u0ac7 \u0aa4\u0aae\u0abe\u0ab0\u0ac0 \u0ab8\u0a82\u0ab8\u0acd\u0aa5\u0abe \u0aa8\u0a95\u0acd\u0a95\u0ac0 \u0a95\u0ab0\u0ac0 \u0ab6\u0a95\u0acd\u0aaf\u0abe \u0aa8\u0ab9\u0ac0\u0a82. \u0a95\u0ac3\u0aaa\u0abe \u0a95\u0ab0\u0ac0 \u0aa4\u0aae\u0abe\u0ab0\u0acb \u0a88\u0aae\u0ac7\u0ab2 \u0aab\u0ab0\u0ac0 \u0ab5\u0ac7\u0ab0\u0abf\u0aab\u0abe\u0aaf \u0a95\u0ab0\u0acb."},
gyM(){return"\u0aa4\u0aae\u0abe\u0ab0\u0ac0 \u0aaa\u0acd\u0ab0\u0acb\u0aab\u0abe\u0a87\u0ab2 \u0ab8\u0ac7\u0ab5 \u0aa5\u0a88, \u0aaa\u0ab0\u0a82\u0aa4\u0ac1 \u0ab8\u0abe\u0a87\u0aa8 \u0a87\u0aa8 \u0aaa\u0ac2\u0ab0\u0acd\u0aa3 \u0aa5\u0a88 \u0ab6\u0a95\u0acd\u0aaf\u0ac1\u0a82 \u0aa8\u0ab9\u0ac0\u0a82. \u0a95\u0ac3\u0aaa\u0abe \u0a95\u0ab0\u0ac0 \u0aab\u0ab0\u0ac0 \u0ab8\u0abe\u0a87\u0aa8 \u0a87\u0aa8 \u0a95\u0ab0\u0acb."},
gyE(){return"\u0aa4\u0aae\u0abe\u0ab0\u0ac0 \u0aae\u0abe\u0ab9\u0abf\u0aa4\u0ac0 \u0a85\u0aaa\u0aa1\u0ac7\u0a9f \u0aa5\u0a88. \u0a96\u0abe\u0aa4\u0ac1\u0a82 \u0ab8\u0a95\u0acd\u0ab0\u0abf\u0aaf \u0a95\u0ab0\u0ab5\u0abe \u0aae\u0abe\u0a9f\u0ac7 \u0a95\u0ac3\u0aaa\u0abe \u0a95\u0ab0\u0ac0 \u0aae\u0ac7\u0aa8\u0ac7\u0a9c\u0ab0 \u0a85\u0aaa\u0acd\u0ab0\u0ac2\u0ab5\u0ab2\u0aa8\u0ac0 \u0ab0\u0abe\u0ab9 \u0a9c\u0ac1\u0a93."},
gyI(){return"\u0aab\u0acb\u0aa8 \u0aa8\u0a82\u0aac\u0ab0 \u0a9c\u0ab0\u0ac2\u0ab0\u0ac0 \u0a9b\u0ac7."},
gyJ(){return"\u0aab\u0acb\u0aa8 \u0aa8\u0a82\u0aac\u0ab0 \u0a93\u0a9b\u0abe\u0aae\u0abe\u0a82 \u0a93\u0a9b\u0acb 10 \u0a85\u0a82\u0a95\u0aa8\u0acb \u0ab9\u0acb\u0ab5\u0acb \u0a9c\u0acb\u0a88\u0a8f."},
gyl(){return"\u0aaa\u0ac2\u0ab0\u0ac1\u0a82 \u0aa8\u0abe\u0aae \u0a9c\u0ab0\u0ac2\u0ab0\u0ac0 \u0a9b\u0ac7."},
