gya(){return"\u0a9c\u0aa8\u0acd\u0aae \u0aa4\u0abe\u0ab0\u0ac0\u0a96 \u0a9c\u0ab0\u0ac2\u0ab0\u0ac0 \u0a9b\u0ac7."},
gyu(){return"\u0ab2\u0acb\u0a95\u0ac7\u0ab6\u0aa8 \u0a9c\u0ab0\u0ac2\u0ab0\u0ac0 \u0a9b\u0ac7."},
gyh(){return"\u0ab0\u0a9c\u0abf\u0ab8\u0acd\u0a9f\u0acd\u0ab0\u0ac7\u0ab6\u0aa8 \u0aaa\u0ac2\u0ab0\u0acd\u0aa3 \u0a95\u0ab0\u0ab5\u0abe \u0aae\u0abe\u0a9f\u0ac7 \u0a95\u0ac3\u0aaa\u0abe \u0a95\u0ab0\u0ac0 \u0aa4\u0aae\u0abe\u0ab0\u0acb \u0aab\u0ac7\u0ab8 \u0a95\u0ac7\u0aaa\u0acd\u0a9a\u0ab0 \u0a95\u0ab0\u0acb."},
gyR(){return"\u0aa4\u0aae\u0abe\u0ab0\u0ac7 \u0a9f\u0ab0\u0acd\u0aae\u0acd\u0ab8 \u0a8f\u0aa8\u0acd\u0aa1 \u0a95\u0aa8\u0acd\u0aa1\u0abf\u0ab6\u0aa8\u0acd\u0ab8 \u0ab8\u0acd\u0ab5\u0ac0\u0a95\u0abe\u0ab0\u0ab5\u0abe \u0a9c \u0aaa\u0aa1\u0ab6\u0ac7."},
gyy(){return"\u0aaa\u0abe\u0ab8\u0a95\u0ac0 \u0ab2\u0acb\u0a97\u0abf\u0aa8"},
gyx(){return"\u0a86 \u0a8f\u0a95\u0abe\u0a89\u0aa8\u0acd\u0a9f \u0aae\u0abe\u0a9f\u0ac7 \u0aaa\u0abe\u0ab8\u0a95\u0ac0 \u0ab2\u0acb\u0a97\u0abf\u0aa8 \u0aaa\u0ab9\u0ac7\u0ab2\u0ac7\u0aa5\u0ac0 \u0a9c \u0ab8\u0a95\u0acd\u0ab0\u0abf\u0aaf \u0a9b\u0ac7"},
gyD(){return"\u0a86 \u0aa1\u0abf\u0ab5\u0abe\u0a87\u0ab8 \u0aaa\u0ab0 \u0a85\u0aa4\u0acd\u0aaf\u0abe\u0ab0\u0ac7 \u0aaa\u0abe\u0ab8\u0a95\u0ac0 \u0ab8\u0ac7\u0a9f\u0a85\u0aaa \u0a89\u0aaa\u0ab2\u0aac\u0acd\u0aa7 \u0aa8\u0aa5\u0ac0"},
gyz(){return"\u0aa4\u0aae\u0abe\u0ab0\u0ac0 \u0aab\u0abf\u0a82\u0a97\u0ab0\u0aaa\u0acd\u0ab0\u0abf\u0aa8\u0acd\u0a9f \u0a85\u0aa5\u0ab5\u0abe \u0aa1\u0abf\u0ab5\u0abe\u0a87\u0ab8 \u0ab2\u0acb\u0a95\u0aa8\u0acb \u0a89\u0aaa\u0aaf\u0acb\u0a97 \u0a95\u0ab0\u0ac0\u0aa8\u0ac7 \u0ab8\u0abe\u0a87\u0aa8 \u0a87\u0aa8 \u0a95\u0ab0\u0acb"},
gyC(){return"\u0aaa\u0abe\u0ab8\u0a95\u0ac0 \u0ab8\u0ac7\u0a9f\u0a85\u0aaa \u0ab8\u0aab\u0ab3\u0aa4\u0abe\u0aaa\u0ac2\u0ab0\u0acd\u0ab5\u0a95 \u0aaa\u0ac2\u0ab0\u0acd\u0aa3 \u0aa5\u0aaf\u0ac1\u0a82."},
yA(a){return a+" \u0aa4\u0aae\u0aa8\u0ac7 \u0aaa\u0abe\u0ab8\u0a95\u0ac0 \u0ab5\u0a97\u0ab0 \u0ab2\u0acb\u0a97 \u0a87\u0aa8 \u0a95\u0ab0\u0ab5\u0abe\u0aae\u0abe\u0a82 \u0a86\u0ab5\u0ac7 \u0a9b\u0ac7."},
gyB(){return"\u0aaa\u0abe\u0ab8\u0a95\u0ac0 \u0ab8\u0ac7\u0a9f\u0a85\u0aaa \u0ab6\u0ab0\u0ac2 \u0a95\u0ab0\u0ac0 \u0ab6\u0a95\u0abe\u0aaf\u0ac1\u0a82 \u0aa8\u0ab9\u0ac0\u0a82. \u0aa4\u0aae\u0aa8\u0ac7 \u0aaa\u0abe\u0ab8\u0a95\u0ac0 \u0ab5\u0a97\u0ab0 \u0ab2\u0acb\u0a97 \u0a87\u0aa8 \u0a95\u0ab0\u0ab5\u0abe\u0aae\u0abe\u0a82 \u0a86\u0ab5\u0ac7 \u0a9b\u0ac7."},
gyN(){return"\u0a85\u0aae\u0ac7 \u0aa4\u0aae\u0abe\u0ab0\u0ac0 \u0aaa\u0acd\u0ab0\u0acb\u0aab\u0abe\u0a87\u0ab2 \u0ab5\u0abf\u0a97\u0aa4\u0acb \u0ab8\u0ac7\u0ab5 \u0a95\u0ab0\u0ac0 \u0ab6\u0a95\u0acd\u0aaf\u0abe \u0aa8\u0ab9\u0ac0\u0a82. \u0a95\u0ac3\u0aaa\u0abe \u0a95\u0ab0\u0ac0 \u0aae\u0abe\u0ab9\u0abf\u0aa4\u0ac0 \u0a9a\u0a95\u0abe\u0ab8\u0acb \u0a85\u0aa8\u0ac7 \u0aab\u0ab0\u0ac0 \u0aaa\u0acd\u0ab0\u0aaf\u0aa4\u0acd\u0aa8 \u0a95\u0ab0\u0acb."},
gwU(){return"\u0a95\u0ac3\u0aaa\u0abe \u0a95\u0ab0\u0ac0 6 \u0a85\u0a82\u0a95 \u0aa6\u0abe\u0a96\u0ab2 \u0a95\u0ab0\u0acb."},
gwV(){return"OTP \u0ab8\u0aae\u0abe\u0aaa\u0acd\u0aa4 \u0aa5\u0aaf\u0acb. \u0a95\u0ac3\u0aaa\u0abe \u0a95\u0ab0\u0ac0 \u0aab\u0ab0\u0ac0 \u0ab5\u0abf\u0aa8\u0a82\u0aa4\u0ac0 \u0a95\u0ab0\u0acb."},
gwW(){return"\u0aa4\u0aae\u0ac7 \u0aa6\u0abe\u0a96\u0ab2 \u0a95\u0ab0\u0ac7\u0ab2\u0acb \u0a95\u0acb\u0aa1 \u0a85\u0aae\u0abe\u0aa8\u0acd\u0aaf \u0a9b\u0ac7."},
gwZ(){return"\u0aa4\u0aae\u0abe\u0ab0\u0ac1\u0a82 \u0ab5\u0ac7\u0ab0\u0abf\u0aab\u0abf\u0a95\u0ac7\u0ab6\u0aa8 \u0ab8\u0ac7\u0ab6\u0aa8 \u0ab8\u0aae\u0abe\u0aaa\u0acd\u0aa4 \u0aa5\u0aaf\u0ac1\u0a82 \u0a9b\u0ac7. \u0a95\u0ac3\u0aaa\u0abe \u0a95\u0ab0\u0ac0 \u0aa8\u0ab5\u0acb \u0a95\u0acb\u0aa1 \u0aae\u0a82\u0a97\u0abe\u0ab5\u0acb."},
gx_(){return"\u0a85\u0aae\u0ac7 \u0a95\u0acb\u0aa1 \u0ab5\u0ac7\u0ab0\u0abf\u0aab\u0abe\u0aaf \u0a95\u0ab0\u0ac0 \u0ab6\u0a95\u0acd\u0aaf\u0abe \u0aa8\u0ab9\u0ac0\u0a82. \u0a95\u0ac3\u0aaa\u0abe \u0a95\u0ab0\u0ac0 \u0aab\u0ab0\u0ac0 \u0aaa\u0acd\u0ab0\u0aaf\u0aa4\u0acd\u0aa8 \u0a95\u0ab0\u0acb."},
gun(){return"\u0a85\u0aae\u0ac7 \u0aa8\u0acb\u0a9f\u0abf\u0aab\u0abf\u0a95\u0ac7\u0ab6\u0aa8 \u0aaa\u0ab0\u0aae\u0abf\u0ab6\u0aa8 \u0a85\u0aaa\u0aa1\u0ac7\u0a9f \u0a95\u0ab0\u0ac0 \u0ab6\u0a95\u0acd\u0aaf\u0abe \u0aa8\u0ab9\u0ac0\u0a82. \u0a95\u0ac3\u0aaa\u0abe \u0a95\u0ab0\u0ac0 \u0aab\u0ab0\u0ac0 \u0aaa\u0acd\u0ab0\u0aaf\u0aa4\u0acd\u0aa8 \u0a95\u0ab0\u0acb."},
guv(){return"\u0aaa\u0a82\u0a9a \u0a87\u0aa8 \u0aab\u0a95\u0acd\u0aa4 \u0aae\u0abe\u0aa8\u0acd\u0aaf task ID \u0ab8\u0abe\u0aa5\u0ac7 \u0a9c \u0aae\u0a82\u0a9c\u0ac2\u0ab0 \u0a9b\u0ac7."},
guz(){return"\u0aaa\u0a82\u0a9a \u0a86\u0a89\u0a9f \u0aab\u0a95\u0acd\u0aa4 \u0aae\u0abe\u0aa8\u0acd\u0aaf task ID \u0ab8\u0abe\u0aa5\u0ac7 \u0a9c \u0aae\u0a82\u0a9c\u0ac2\u0ab0 \u0a9b\u0ac7."},
gtS(){return"\u0aa4\u0aae\u0ac7 \u0aaa\u0ab9\u0ac7\u0ab2\u0ac7\u0aa5\u0ac0 \u0a9c punched in \u0a9b\u0acb."},
gut(){return"\u0aaa\u0a82\u0a9a \u0a86\u0a89\u0a9f \u0a95\u0ab0\u0aa4\u0abe \u0aaa\u0ab9\u0ac7\u0ab2\u0abe \u0aa4\u0aae\u0abe\u0ab0\u0ac7 \u0aaa\u0a82\u0a9a \u0a87\u0aa8 \u0a95\u0ab0\u0ab5\u0ac1\u0a82 \u0a9c\u0ab0\u0ac2\u0ab0\u0ac0 \u0a9b\u0ac7."},
gtZ(){return"\u0a85\u0a9f\u0ac7\u0aa8\u0acd\u0aa1\u0aa8\u0acd\u0ab8 \u0ab2\u0acb\u0a97 \u0ab8\u0aab\u0ab3\u0aa4\u0abe\u0aaa\u0ac2\u0ab0\u0acd\u0ab5\u0a95 \u0a8f\u0a95\u0acd\u0ab8\u0aaa\u0acb\u0ab0\u0acd\u0a9f \u0aa5\u0aaf\u0acb."},
gtY(){return"\u0a85\u0aae\u0ac7 \u0a85\u0a9f\u0ac7\u0aa8\u0acd\u0aa1\u0aa8\u0acd\u0ab8 \u0ab2\u0acb\u0a97 \u0a8f\u0a95\u0acd\u0ab8\u0aaa\u0acb\u0ab0\u0acd\u0a9f \u0a95\u0ab0\u0ac0 \u0ab6\u0a95\u0acd\u0aaf\u0abe \u0aa8\u0ab9\u0ac0\u0a82. \u0a95\u0ac3\u0aaa\u0abe \u0a95\u0ab0\u0ac0 \u0aab\u0ab0\u0ac0 \u0aaa\u0acd\u0ab0\u0aaf\u0aa4\u0acd\u0aa8 \u0a95\u0ab0\u0acb."},
gtR(){return"\u0a85\u0aae\u0ac7 \u0a85\u0a9f\u0ac7\u0aa8\u0acd\u0aa1\u0aa8\u0acd\u0ab8 \u0a8f\u0a95\u0acd\u0ab6\u0aa8 \u0aaa\u0ac2\u0ab0\u0acd\u0aa3 \u0a95\u0ab0\u0ac0 \u0ab6\u0a95\u0acd\u0aaf\u0abe \u0aa8\u0ab9\u0ac0\u0a82. \u0a95\u0ac3\u0aaa\u0abe \u0a95\u0ab0\u0ac0 \u0aab\u0ab0\u0ac0 \u0aaa\u0acd\u0ab0\u0aaf\u0aa4\u0acd\u0aa8 \u0a95\u0ab0\u0acb."},
gu7(){return"\u0a85\u0aae\u0ac7 \u0aa4\u0aae\u0abe\u0ab0\u0ac0 \u0aaa\u0acd\u0ab0\u0acb\u0aab\u0abe\u0a87\u0ab2 \u0ab2\u0acb\u0aa1 \u0a95\u0ab0\u0ac0 \u0ab6\u0a95\u0acd\u0aaf\u0abe \u0aa8\u0ab9\u0ac0\u0a82. \u0a95\u0ac3\u0aaa\u0abe \u0a95\u0ab0\u0ac0 \u0ab0\u0abf\u0aab\u0acd\u0ab0\u0ac7\u0ab6 \u0a95\u0ab0\u0ac0 \u0aab\u0ab0\u0ac0 \u0aaa\u0acd\u0ab0\u0aaf\u0aa4\u0acd\u0aa8 \u0a95\u0ab0\u0acb."},
gu5(){return"\u0a85\u0aae\u0ac7 \u0aa4\u0aae\u0abe\u0ab0\u0acb \u0a85\u0a9f\u0ac7\u0aa8\u0acd\u0aa1\u0aa8\u0acd\u0ab8 \u0ab2\u0acb\u0a97 \u0ab2\u0acb\u0aa1 \u0a95\u0ab0\u0ac0 \u0ab6\u0a95\u0acd\u0aaf\u0abe \u0aa8\u0ab9\u0ac0\u0a82. \u0a95\u0ac3\u0aaa\u0abe \u0a95\u0ab0\u0ac0 \u0aab\u0ab0\u0ac0 \u0aaa\u0acd\u0ab0\u0aaf\u0aa4\u0acd\u0aa8 \u0a95\u0ab0\u0acb."},
