gzV(){return"\u0caa\u0cbe\u0cb8\u0ccd\u200c\u0c95\u0cc0 \u0cb8\u0cc6\u0c9f\u0caa\u0ccd \u0c97\u0ccd\u0cb0\u0cbe\u0c82\u0c9f\u0ccd \u0cae\u0cb0\u0cb3\u0cbf \u0cb2\u0cad\u0ccd\u0caf\u0cb5\u0cbe\u0c97\u0cb2\u0cbf\u0cb2\u0ccd\u0cb2. \u0cac\u0ca6\u0cb2\u0cbe\u0c97\u0cbf \u0ca8\u0cbf\u0cae\u0ccd\u0cae\u0ca8\u0ccd\u0ca8\u0cc1 OTP \u0cae\u0cc2\u0cb2\u0c95 \u0cb2\u0cbe\u0c97\u0cbf\u0ca8\u0ccd \u0cae\u0cbe\u0ca1\u0cb2\u0cbe\u0c97\u0cc1\u0ca4\u0ccd\u0ca4\u0cbf\u0ca6\u0cc6."},
gye(){return"\u0cab\u0cc7\u0cb8\u0ccd \u0caf\u0cb6\u0cb8\u0ccd\u0cb5\u0cbf\u0caf\u0cbe\u0c97\u0cbf \u0c95\u0ccd\u0caf\u0cbe\u0caa\u0ccd\u0c9a\u0cb0\u0ccd \u0c86\u0c97\u0cbf\u0ca6\u0cc6."},
gyg(){return"\u0cab\u0cc7\u0cb8\u0ccd \u0c87\u0cae\u0cc7\u0c9c\u0ccd \u0caa\u0ccd\u0cb0\u0cca\u0cb8\u0cc6\u0cb8\u0ccd \u0c86\u0c97\u0cb2\u0cbf\u0cb2\u0ccd\u0cb2. \u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 \u0cae\u0ca4\u0ccd\u0ca4\u0cc6 \u0caa\u0ccd\u0cb0\u0caf\u0ca4\u0ccd\u0ca8\u0cbf\u0cb8\u0cbf."},
gyt(){return"\u0cb2\u0cca\u0c95\u0cc7\u0cb6\u0ca8\u0ccd \u0caf\u0cb6\u0cb8\u0ccd\u0cb5\u0cbf\u0caf\u0cbe\u0c97\u0cbf \u0c95\u0ccd\u0caf\u0cbe\u0caa\u0ccd\u0c9a\u0cb0\u0ccd \u0c86\u0c97\u0cbf\u0ca6\u0cc6."},
gys(){return u.F},
